'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isUndefined = require( '@stdlib/assert/is-undefined' );
var join = require( '@stdlib/array/base/join' );
var defaults = require( './../defaults.js' );
var resolveValue = require( './resolve_value.js' );


// VARIABLES //

var PROPS = [
	'align',
	'anchor',
	'angle',
	'baseline',
	'color',
	'dx',
	'dy',
	'font',
	'fontSize',
	'fontStyle',
	'fontWeight',
	'frame',
	'limit',
	'lineHeight',
	'offset',
	'orient',
	'subtitleColor',
	'subtitleFont',
	'subtitleFontSize',
	'subtitleFontStyle',
	'subtitleFontWeight',
	'subtitleFontLineHeight',
	'subtitlePadding'
];
var TEXT_PROPS = [
	'subtitle',
	'title'
];


// FUNCTIONS //

/**
* Resolves a text configuration value.
*
* @private
* @param {Object} src - source object
* @param {Object} defaults - defaults object
* @param {Object} dest - destination object
* @param {string} prop - property name
*/
function resolveTextValue( src, defaults, dest, prop ) {
	var v = src[ prop ];
	if ( !isSignalReference( v ) ) {
		if ( isUndefined( v ) ) {
			dest[ prop ] = defaults[ prop ];
		} else if ( isString( v ) ) {
			dest[ prop ] = v;
		} else {
			dest[ prop ] = join( v, '\n' );
		}
	}
}


// MAIN //

/**
* Synchronizes an editor configuration with a provided schema.
*
* @private
* @param {Object} conf - configuration object
* @param {Object} schema - visualization schema
* @returns {Object} mutated configuration object
*/
function config( conf, schema ) {
	var obj;
	var def;
	var i;

	obj = schema.title;
	if ( !obj ) {
		return conf;
	}
	def = defaults.title;
	for ( i = 0; i < PROPS.length; i++ ) {
		resolveValue( obj, def, conf, PROPS[ i ] );
	}
	for ( i = 0; i < TEXT_PROPS.length; i++ ) {
		resolveTextValue( obj, def, conf, TEXT_PROPS[ i ] );
	}
	return conf;
}


// EXPORTS //

module.exports = config;
